--drop procedure seaware.plan_forecast_actuals_sp();
CREATE OR REPLACE PROCEDURE seaware.plan_forecast_actuals_sp()  
AS $$ 
DECLARE
	sql varchar(20000) DEFAULT '';
	sql_str1 varchar(5000) DEFAULT '';
	sql_select_str varchar(5000) DEFAULT '';
	sql_str2 varchar(5000) DEFAULT '';	
	sql_case_str varchar(5000) DEFAULT '';
	sql_str3 varchar(10000) DEFAULT '';
	metric_lkp   RECORD;
    cur_metric_vals CURSOR  
		FOR SELECT distinct forecast_metric_desc from hive_schema_stg.seaware_forecastmetric_lkp;

BEGIN
	sql_str1:= 'create or replace view seaware.plan_forecast_actuals_vw as WITH max_snapshot_date as (select sail.src_sail_id src_sail_id,max(snapshot_date) snapshot_date, Datediff(week,Dateadd(day,-1,sail_date_from),Dateadd(day,-1,snapshot_date)) week_index from hive_schema_stg.seaware_revenue_fact fact join seaware.seaware_sail_dim sail on fact.sail_id=sail.sail_id group by sail.src_sail_id,week_index ) select distinct plan_forecast.cabin_ctg_generic, plan_forecast.package_type,plan_forecast.src_sail_id, actuals.sail_days, plan_forecast.week_index, plan_forecast.sunday_date, plan_forecast.forecast_version_desc,';
	sql_str2:= ' actuals.Actual_Gross_Onboard_Revenue, actuals.Actual_Gross_Onboard_Revenue_USD, actuals.actual_gross_other_revenue, actuals.actual_gross_other_revenue_usd, actuals.actual_gross_ticket_revenue, actuals.actual_gross_ticket_revenue_usd, actuals.actual_gross_total_revenue, actuals.actual_gross_total_revenue_usd, actuals.actual_other_gpd_usd, actuals.actual_ticket_gpd_usd, actuals.actual_total_gpd_usd, actuals.Net_Ticket_Revenue, actuals.Net_Ticket_Revenue_USD, actuals.Net_APD, actuals.Net_APD_USD, actuals.Guest_Count, cabin_fact.cabin_occ, cabin_fact.ok_abs, cabin_fact.gty_abs, cabin_fact.ok_gtry_rstr_abs, cabin_fact.num_of_cabins, cabin_fact.na_abs, cabin_fact.ok_wgt, cabin_fact.gty_wgt, cabin_fact.wtl_abs, cabin_fact.wtl_wgt, cabin_fact.avail_abs, cabin_fact.avail_wgt, cabin_fact.num_of_reserved FROM (SELECT seaware_plan_forecast_header_dim.cabin_ctg_generic AS cabin_ctg_generic,   seaware_plan_forecast_header_dim.package_type AS package_type,   seaware_sail_dim.src_sail_id AS src_sail_id,   seaware_plan_forecast_value_dim.week_index AS week_index, case when (date_part(dow,(dateadd(week,seaware_plan_forecast_value_dim.week_index,seaware_sail_dim.sail_date_from))))=0 then (dateadd(week,seaware_plan_forecast_value_dim.week_index,seaware_sail_dim.sail_date_from)) else next_day((dateadd(week,seaware_plan_forecast_value_dim.week_index,seaware_sail_dim.sail_date_from)),''Sunday'')  end as sunday_date,    seaware_forecastversion_lkp.forecast_version_desc as forecast_version_desc ';
	sql_str3:= ' FROM seaware.seaware_plan_forecast_header_dim seaware_plan_forecast_header_dim   INNER JOIN seaware.seaware_plan_forecast_value_dim seaware_plan_forecast_value_dim ON (seaware_plan_forecast_header_dim.plan_forecast_id = seaware_plan_forecast_value_dim.plan_forecast_id)   INNER JOIN seaware.seaware_forecastmetric_lkp seaware_forecastmetric_lkp ON (seaware_plan_forecast_header_dim.forecast_metric_id = seaware_forecastmetric_lkp.forecast_metric_id)   INNER JOIN seaware.seaware_forecastversion_lkp seaware_forecastversion_lkp ON (seaware_plan_forecast_header_dim.forecast_version_id = seaware_forecastversion_lkp.forecast_version_id)   INNER JOIN seaware.seaware_sail_dim seaware_sail_dim ON (seaware_plan_forecast_header_dim.sail_id = seaware_sail_dim.sail_id) GROUP BY cabin_ctg_generic,   package_type,   src_sail_id,   week_index,   forecast_version_desc, sail_date_from order by src_sail_id, week_index  ) as plan_forecast left join (SELECT generic_category, package_type, tmp.src_sail_id src_sail_id, sail_days, tmp.snapshot_date snapshot_date, tmp.week_index week_index, forecast_version_desc, forecast_metric_desc, Sum(actual_gross_onboard_revenue) actual_gross_onboard_revenue, Sum(actual_gross_onboard_revenue_usd) actual_gross_onboard_revenue_usd, Sum(actual_gross_other_revenue) actual_gross_other_revenue, Sum(actual_gross_other_revenue_usd) actual_gross_other_revenue_usd, Sum(actual_gross_ticket_revenue) actual_gross_ticket_revenue, Sum(actual_gross_ticket_revenue_usd) actual_gross_ticket_revenue_usd, Sum(actual_gross_total_revenue) actual_gross_total_revenue, Sum(actual_gross_total_revenue_usd) actual_gross_total_revenue_usd, Sum(actual_other_gpd_usd) actual_other_gpd_usd, Sum(actual_ticket_gpd_usd) actual_ticket_gpd_usd, Sum(actual_total_gpd_usd) actual_total_gpd_usd, Sum(net_ticket_revenue) net_ticket_revenue, Sum(net_ticket_revenue_usd) net_ticket_revenue_usd, Sum(net_apd) net_apd, Sum(net_apd_usd) net_apd_usd, Sum(guest_count) guest_count FROM (SELECT cab_res.generic_category, pkg.package_type, sail.src_sail_id, sail.sail_days, snapshot_date, Datediff(WEEK, Dateadd(DAY, -1, sail_date_from), Dateadd(DAY, -1, snapshot_date)) week_index, ''Actuals'' forecast_version_desc, ''Actuals'' forecast_metric_desc, Sum(actual_gross_onboard_revenue) AS actual_gross_onboard_revenue, Sum(actual_gross_onboard_revenue_usd) AS actual_gross_onboard_revenue_usd, Sum(actual_gross_other_revenue) actual_gross_other_revenue, Sum(actual_gross_other_revenue_usd) actual_gross_other_revenue_usd, Sum(actual_gross_ticket_revenue) actual_gross_ticket_revenue, Sum(actual_gross_ticket_revenue_usd) actual_gross_ticket_revenue_usd, Sum(actual_gross_total_revenue) actual_gross_total_revenue, Sum(actual_gross_total_revenue_usd) actual_gross_total_revenue_usd, Sum(actual_gross_other_revenue_usd) /sail.sail_days actual_other_gpd_usd, Sum(actual_gross_ticket_revenue_usd)/sail.sail_days actual_ticket_gpd_usd, Sum(actual_gross_total_revenue_usd) /sail.sail_days actual_total_gpd_usd, Sum(CASE WHEN it.invoice_item_type IN (''VOYAGE FARE'', ''MANUAL ADJ'') THEN amount ELSE 0 END) AS net_ticket_revenue, Sum(CASE WHEN it.invoice_item_type IN (''VOYAGE FARE'', ''MANUAL ADJ'') THEN amount_usd ELSE 0 END) AS net_ticket_revenue_usd, net_ticket_revenue /sail.sail_days AS net_apd, net_ticket_revenue_usd/sail.sail_days AS net_apd_usd, Count(DISTINCT rev.guest_id) AS guest_count FROM seaware.seaware_revenue_fact rev INNER JOIN seaware.seaware_sail_dim sail ON (rev.sail_id = sail.sail_id) INNER JOIN seaware.seaware_package_dim pkg ON (rev.package_id = pkg.package_id) INNER JOIN (SELECT generic_category, bcrd.res_id, bcrd.guest_id FROM seaware.seaware_booked_cabin_reservation_dim bcrd JOIN (SELECT res_id, guest_id, Max(rec_end_dttm) rec_end_dttm FROM seaware.seaware_booked_cabin_reservation_dim GROUP BY res_id, guest_id) bcrd_m ON bcrd.res_id=bcrd_m.res_id AND bcrd.guest_id=bcrd_m.guest_id AND bcrd.rec_end_dttm=bcrd_m.rec_end_dttm) AS cab_res ON (rev.res_id = cab_res.res_id AND rev.guest_id = cab_res.guest_id) INNER JOIN seaware.seaware_invoice_item_type_lkp it ON (rev.invoice_item_type_id = it.invoice_item_type_id) GROUP BY generic_category, package_type, sail.src_sail_id, sail.sail_date_from, snapshot_date, sail_days HAVING week_index > -111 AND week_index < 1) tmp INNER JOIN max_snapshot_date msd on (tmp.src_sail_id=msd.src_sail_id and tmp.week_index=msd.week_index and tmp.snapshot_date=msd.snapshot_date) GROUP BY generic_category, package_type, tmp.src_sail_id, sail_days, tmp.snapshot_date, tmp.week_index, forecast_version_desc, forecast_metric_desc) as actuals on plan_forecast.src_sail_id = actuals.src_sail_id and plan_forecast.cabin_ctg_generic = actuals.generic_category and plan_forecast.package_type = actuals.package_type and plan_forecast.week_index = actuals.week_index left join ( SELECT generic_category,package_type, tmp.src_sail_id src_sail_id, tmp.snapshot_date snapshot_date, tmp.week_index week_index, ok_abs, gty_abs, ok_gtry_rstr_abs,num_of_cabins, na_abs, ok_wgt, gty_wgt, wtl_abs, wtl_wgt, avail_abs, avail_wgt, num_of_reserved, cabin_occ FROM ( SELECT cab_fct.generic_category, pkg.package_type, sail.src_sail_id, snapshot_date snapshot_date, Datediff(week,Dateadd(day,-1,sail_date_from),Dateadd(day,-1,snapshot_date)) week_index, Sum(Nvl(ok_abs,0)) ok_abs, Sum(Nvl(gty_abs,0)) gty_abs, Sum(Nvl(ok_gtry_rstr_abs,0)) ok_gtry_rstr_abs, Sum(Nvl(num_of_cabins,0)) num_of_cabins, Sum(Nvl(na_abs,0)) na_abs, Sum(Nvl(ok_wgt,0)) ok_wgt, Sum(Nvl(gty_wgt,0)) gty_wgt, Sum(Nvl(wtl_abs,0)) wtl_abs, Sum(Nvl(wtl_wgt,0)) wtl_wgt, Sum(Nvl(avail_abs,0)) avail_abs, Sum(Nvl(avail_wgt,0)) avail_wgt, Sum(Nvl(num_of_reserved,0)) num_of_reserved, CASE WHEN ( Sum(Nvl(num_of_cabins,0))-Sum(Nvl(na_abs,0)))::float=0 THEN 0 ELSE ((Sum(Nvl(ok_abs,0)) + Sum(Nvl(gty_abs,0)) + Sum(Nvl(ok_gtry_rstr_abs,0)))::float / (Sum(Nvl(num_of_cabins,0))-Sum(Nvl(na_abs,0)))::float)::float*100 END AS cabin_occ FROM hive_schema_stg.seaware_sail_cabin_fact cab_fct INNER JOIN seaware.seaware_sail_dim sail ON ( cab_fct.sail_id = sail.sail_id) INNER JOIN seaware.seaware_package_dim pkg ON ( sail.src_sail_id = pkg.src_sail_id) GROUP BY cab_fct.generic_category, pkg.package_type, sail.src_sail_id, snapshot_date, week_index ) tmp INNER JOIN max_snapshot_date msd on (tmp.src_sail_id=msd.src_sail_id and tmp.week_index=msd.week_index and tmp.snapshot_date=msd.snapshot_date) ) as cabin_fact on plan_forecast.src_sail_id = cabin_fact.src_sail_id and plan_forecast.cabin_ctg_generic = cabin_fact.generic_category and plan_forecast.package_type = cabin_fact.package_type and plan_forecast.week_index = cabin_fact.week_index with no schema binding ;';

  OPEN cur_metric_vals;
  LOOP
      FETCH cur_metric_vals INTO metric_lkp;
      EXIT WHEN NOT FOUND;
	  sql_select_str := sql_select_str || ' plan_forecast."' || metric_lkp.forecast_metric_desc  || '",';	
      sql_case_str := sql_case_str || ',' || 'sum(case when seaware_forecastmetric_lkp.forecast_metric_desc = ''' || metric_lkp.forecast_metric_desc || ''' then value else 0 end) as "' || metric_lkp.forecast_metric_desc || '" ';
  END LOOP;  
  sql := sql_str1 || sql_select_str || sql_str2 || sql_case_str || sql_str3;
	--out_var_v := sql;
	EXECUTE sql;
END;
$$ LANGUAGE plpgsql;

--call seaware.plan_forecast_actuals_sp();
